<p><a href="<?= e_attr($basePath) ?>/store">← Back to store</a></p><section class="store-hero" style="align-items:center"><div><?php if($product['image_url']): ?><img class="product-image" style="border-radius:1rem" src="<?= e_attr($product['image_url']) ?>" alt=""><?php else: ?><div class="product-image empty" style="border-radius:1rem">Freshly prepared for you</div><?php endif; ?></div><div><p class="eyebrow"><?= e($product['sku']) ?></p><h1><?= e($product['name']) ?></h1><p><?= e($product['description']) ?></p><p class="price"><?= e($product['currency']) ?> $<?= number_format((int)$product['price_minor']/100,2) ?></p><?php if((int)$product['track_inventory']&&(int)$product['stock_quantity']<1): ?><div class="store-error">Currently unavailable</div><?php else: ?><form method="post" action="<?= e_attr($basePath) ?>/cart/add" class="product-actions"><?= $csrf->field() ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><label>Quantity<input type="number" name="quantity" value="1" min="1" max="99"></label><button class="btn">Add to cart</button></form><?php endif; ?></div></section>
